$('zoom').oninput=e=>{zoom=Number(e.target.value);timeline();draw()};
$('srt').onclick=()=>{let stamp=t=>new Date(Math.round(t*1000)).toISOString().slice(11,23).replace('.',',');let cues=project.clips.filter(c=>!c.asset&&c.text).sort((a,b)=>a.start-b.start);if(!cues.length)return say('Add a title or import captions first.');let lines=cues.map((c,i)=>[i+1,stamp(c.start)+' --> '+stamp(c.start+c.dur),c.text].join('\n'));download(new Blob([lines.join('\n\n')]),project.name+'.srt')};
$('subtitle').onchange=async e=>{let f=e.target.files[0];e.target.value='';if(!f)return;let cues=[];for(let block of (await f.text()).trim().replaceAll('\r','').split(/\n\s*\n/)){let m=block.match(/(\d+):(\d+):(\d+)[,.](\d+)\s*-->\s*(\d+):(\d+):(\d+)[,.](\d+)[^\n]*\n([\s\S]+)/);if(!m)continue;let seconds=i=>+m[i]*3600+ +m[i+1]*60+ +m[i+2]+Number('0.'+m[i+3]),s=snap(seconds(1)),d=snap(seconds(5)-s);if(d>0)cues.push({...clip('',s,0,d),text:m[9],y:88,size:4})}if(!cues.length)return say('No valid SRT cues found.');remember();project.clips.push(...cues);sel=cues[0].id;edited();say(cues.length+' captions imported.')};
document.querySelectorAll('nav button').forEach(b=>b.onclick=()=>{tab=b.dataset.tab;document.querySelectorAll('nav button').forEach(v=>v.classList.toggle('active',v===b));props()});
document.addEventListener('keydown',e=>{if(exporting||$('dialog').open||/INPUT|TEXTAREA|SELECT/.test(e.target.tagName))return;let k=e.key.toLowerCase(),ctrl=e.ctrlKey||e.metaKey;let action=ctrl&&k==='k'?split:ctrl&&k==='z'?()=>undo(e.shiftKey):ctrl&&k==='s'?()=>$('save').click():k===' '?play:k==='arrowleft'?()=>seek(time-1/fps):k==='arrowright'?()=>seek(time+1/fps):['delete','backspace'].includes(k)?()=>removeClip(e.shiftKey):k==='home'?()=>seek(0):null;if(action){e.preventDefault();action()}});
$('export').onclick=()=>{closeSource();pause();if(!end())return say('Add a clip before exporting.');if(project.clips.some(c=>c.asset&&!url(asset(c.asset))))return say('Relink offline assets before exporting.');if(!window.MediaRecorder||!canvas.captureStream)return say('This browser lacks canvas recording. Try desktop Chrome or Edge.');let list=$('format');list.replaceChildren();for(let [name,types] of [['MP4',['video/mp4;codecs=avc1.42E01E,mp4a.40.2','video/mp4']],['WebM',['video/webm;codecs=vp9,opus','video/webm;codecs=vp8,opus','video/webm']]]){let type=types.find(t=>MediaRecorder.isTypeSupported(t));if(type)list.add(new Option(name,type))}if(!list.length)return say('No supported recording format found.');$('dialog').showModal()};
$('render').onclick=async()=>{if(exporting)return;let saved=time,stream;function finish(){pause();exporting=false;rec=null;stream?.getVideoTracks().forEach(t=>t.stop());document.querySelector('main').inert=false;document.querySelector('header').inert=false;document.querySelector('nav').inert=false;time=saved;dimensions();draw()}
try{await audio();exporting=true;time=0;dimensions(+$('quality').value);draw();$('render').disabled=true;let ready=[...nodes.values()].filter(n=>n.el.readyState<2).map(n=>new Promise((yes,no)=>{let timer=setTimeout(()=>no(Error('Media did not finish loading')),10000);n.el.addEventListener('loadeddata',()=>{clearTimeout(timer);yes()},{once:true})}));await Promise.all(ready);draw();
stream=canvas.captureStream(fps);for(let t of destination.stream.getAudioTracks())stream.addTrack(t);let mimeType=$('format').value;rec=new MediaRecorder(stream,{mimeType,videoBitsPerSecond:+$('quality').value>=2160?30000000:8000000});let chunks=[];rec.ondataavailable=e=>{if(e.data.size)chunks.push(e.data)};let failed=false;rec.onerror=()=>{failed=true;say('Encoder failed. Try a lower resolution.')};rec.onstop=()=>{if(!failed&&chunks.length){download(new Blob(chunks,{type:mimeType}),project.name+(mimeType.includes('mp4')?'.mp4':'.webm'));say('Export finished.')}finish()};$('dialog').close();document.querySelector('main').inert=document.querySelector('header').inert=document.querySelector('nav').inert=true;say('Exporting in real time. Keep this tab visible.');rec.start(500);await play()}catch(e){finish();say('Export failed: '+e.message)}finally{$('render').disabled=false}};
(async()=>{let saved;try{saved=JSON.parse(localStorage.getItem('AJVideosSequence'))}catch{}if(saved)try{await restore(saved);return}catch{}ui();draw()})();
